CREATE TABLE IF NOT EXISTS users ( lic TEXT PRIMARY KEY, tail TEXT, email TEXT, name TEXT, status TEXT, first_seen INTEGER, last_seen INTEGER, last_check INTEGER, expires_at TEXT, ended_at INTEGER ); CREATE TABLE IF NOT EXISTS devices ( iid TEXT PRIMARY KEY, lic TEXT, label TEXT, ver TEXT, first_seen INTEGER, last_seen INTEGER ); CREATE INDEX IF NOT EXISTS devices_lic ON devices(lic); CREATE TABLE IF NOT EXISTS guests ( h TEXT PRIMARY KEY, tail TEXT, name TEXT, created INTEGER, expires INTEGER, revoked INTEGER, last_seen INTEGER, expired_logged INTEGER ); CREATE TABLE IF NOT EXISTS events ( id INTEGER PRIMARY KEY AUTOINCREMENT, t INTEGER, lic TEXT, tail TEXT, email TEXT, ev TEXT, detail TEXT ); CREATE INDEX IF NOT EXISTS events_lic ON events(lic, t); CREATE INDEX IF NOT EXISTS events_t ON events(t); CREATE TABLE IF NOT EXISTS rl ( k TEXT PRIMARY KEY, n INTEGER, t INTEGER );
